CREATE TEMP TABLE catalogue_input ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id":"927ec471-6424-5159-8365-56ce50ff0660","source_id":"0545","name_en":"kettlebell plyo push-up","name_ar":"\u062a\u0645\u0631\u064a\u0646 \u0627\u0644\u0636\u063a\u0637 Kettlebell plyo","match_names":["kettlebell plyo push-up"],"muscle":"chest","equipment":"kettlebell","aliases":["kettlebell plyo push-up"],"logging_mode":"weighted_reps","load_convention":"per_hand","guidance":{"steps_en":"Start in a high plank position with your hands on the kettlebells, shoulder-width apart.\nLower your chest towards the ground, keeping your elbows close to your body.\nPush through your hands explosively, lifting your hands off the kettlebells and extending your arms fully.\nLand softly back on the kettlebells and immediately lower your chest back down for the next repetition.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0641\u064a \u0648\u0636\u0639 \u0627\u0644\u0644\u0648\u062d \u0627\u0644\u062e\u0634\u0628\u064a \u0627\u0644\u0645\u0631\u062a\u0641\u0639 \u0645\u0639 \u0648\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 Kettlebells\u060c \u0645\u0639 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u062e\u0641\u0636 \u0635\u062f\u0631\u0643 \u0646\u062d\u0648 \u0627\u0644\u0623\u0631\u0636\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0631\u064a\u0628\u064a\u0646 \u0645\u0646 \u062c\u0633\u0645\u0643.\n\u0627\u062f\u0641\u0639 \u064a\u062f\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u062a\u0641\u062c\u0631\u060c \u0648\u0627\u0631\u0641\u0639 \u064a\u062f\u064a\u0643 \u0639\u0646 \u0627\u0644\u0643\u064a\u062a\u0644 \u0628\u064a\u0644 \u0648\u0645\u062f \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644.\n\u0647\u0628\u0637 \u0628\u0647\u062f\u0648\u0621 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0639\u0644\u0649 Kettlebell \u0648\u0642