n":"bodyweight","guidance":{"steps_en":"Start in a push-up position with your hands shoulder-width apart and your body straight.\nEngage your core and slowly shift your weight forward, bringing your shoulders past your hands.\nKeep your elbows slightly bent and your body straight as you lean forward.\nHold this position for a few seconds, then slowly return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0628\u062f\u0623 \u0628\u0648\u0636\u0639\u064a\u0629 \u0627\u0644\u0636\u063a\u0637 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u064a\u062f\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062d\u0631\u0643 \u0648\u0632\u0646\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0645\u0627 \u064a\u062c\u0639\u0644 \u0643\u062a\u0641\u064a\u0643 \u062e\u0644\u0641 \u064a\u062f\u064a\u0643.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0645\u0631\u0641\u0642\u064a\u0643 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0648\u0623\u0646\u062a \u062a\u0645\u064a\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0648\u0636\u0639 \u0644\u0628\u0636\u0639 \u062b\u0648\u0627\u0646\u060c \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"3300","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["shoulders","chest","triceps"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/3300-LYJodFS.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/3300-LYJodFS.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"528db1a3-6cb8-524e-83f3-1c10a79dda3d","source_id":"2271","name_en":"left hook. boxing","name_ar":"\u0627\u0644\u062e\u0637\u0627\u0641 \u0627\u0644\u0623\u064a\u0633\u0631. \u0627\u0644\u0645\u0644\u0627\u0643\u0645\u0629","match_names":["left hook. boxing"],"muscle":"shoulders","equipment":"bodyweight","aliases":["left hook. boxing"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Stand with your feet shoulder-width apart and your knees slightly bent.\nKeep your left hand up to protect your face and your right hand by your chin.\nRotate your hips and pivot on your left foot as you extend your left arm forward in a punching motion.\nTwist your torso and engage your core muscles to generate power in the punch.\nSnap your arm back to the starting position and repeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0628\u0642\u0650 \u064a\u062f\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0645\u0631\u0641\u0648\u0639\u0629 \u0644\u062d\u0645\u0627\u064a\u0629 \u0648\u062c\u0647\u0643 \u0648\u064a\u062f\u0643 \u0627\u0644\u064a\u0645\u0646\u0649 \u0628\u0627\u0644\u0642\u0631\u0628 \u0645\u0646 \u0630\u0642\u0646\u0643.\n\u0642\u0645 \u0628\u062a\u062f\u0648\u064a\u0631 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0648\u0627\u0644\u062f\u0648\u0631\u0627\u0646 \u0639\u0644\u0649 \u0642\u062f\u0645\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0628\u064a\u0646\u0645\u0627 \u062a\u0645\u062f \u0630\u0631\u0627\u0639\u0643 \u0627\u0644\u064a\u0633\u0631\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0641\u064a \u062d\u0631\u0643\u0629 \u0627\u0644\u0644\u0643\u0645.\n\u0642\u0645 \u0628\u062a\u062d\u0631\u064a\u0641 \u062c\u0630\u0639\u0643 \u0648\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a\u0643 \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629 \u0644\u062a\u0648\u0644\u064a\u062f \u0627\u0644\u0637\u0627\u0642\u0629 \u0641\u064a \u0627\u0644\u0644\u0643\u0645\u0629.\n\u0623\u0639\u062f \u0630\u0631\u0627\u0639\u0643 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0644\u0639\u062f\u062f \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0645\u0637\u0644\u0648\u0628\u0629.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2271","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["biceps","triceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2271-hoXt6wv.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2271-hoXt6wv.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"5e02355d-dd13-5d03-898b-d03afe27e89b","source_id":"0570","name_en":"leg pull in flat bench","name_ar":"\u0633\u062d\u0628 \u0627\u0644\u0633\u0627\u0642 \u0641\u064a \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d","match_names":["leg pull in flat bench"],"muscle":"core","equipment":"bodyweight","aliases":["leg pull in flat bench"],"logging_mode":"bodyweight_reps","load_convention":"bodyweight","guidance":{"steps_en":"Sit on a flat bench with your legs extended straight out in front of you.\nPlace your hands on the bench beside your hips for support.\nEngage your abs and lift your legs off the ground, bringing your knees towards your chest.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0645\u0642\u0639\u062f \u0645\u0633\u0637\u062d \u0645\u0639 \u0645\u062f \u0633\u0627\u0642\u064a\u0643 \u0628\u0634\u0643\u0644 \u0645\u0633\u062a\u0642\u064a\u0645 \u0623\u0645\u0627\u0645\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0639\u062f \u0628\u062c\u0627\u0646\u0628 \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u062f\u0639\u0645.\n\u0642\u0645 \u0628\u0634\u062f \u0639\u0636\u0644\u0627\u062a \u0628\u0637\u0646\u0643 \u0648\u0627\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0639\u0646 \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u062c\u0644\u0628 \u0631\u0643\u0628\u062a\u064a\u0643 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0570","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"abs","secondary_muscles":["hip flexors","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0570-OyoZ3Pu.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0570-OyoZ3Pu.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"99db3202-f7ae-5ca8-8770-d3a35c93deb7","source_id":"1576","name_en":"leg up hamstring stretch","name_ar":"\u062a\u0645\u062a\u062f \u0627\u0644\u0633\u0627\u0642 \u062d\u062a\u0649 \u0627\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629","match_names":["leg up hamstring stretch"],"muscle":"hamstrings","equipment":"bodyweight","aliases":["leg up hamstring stretch"],"logging_mode":"timed","load_convention":"bodyweight","guidance":{"steps_en":"Lie flat on your back with your legs extended.\nBend one knee and bring it towards your chest, holding onto your thigh or shin.\nStraighten your leg as much as possible while keeping it elevated.\nHold the stretch for 20-30 seconds.\nRepeat with the other leg.","steps_ar":"\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0638\u0647\u0631\u0643 \u0645\u0639 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643.\n\u0627\u062b\u0646\u0650 \u0631\u0643\u0628\u0629 \u0648\u0627\u062d\u062f\u0629 \u0648\u0627\u062f\u0641\u0639\u0647\u0627 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0645\u0645\u0633\u0643\u064b\u0627 \u0628\u0641\u062e\u0630\u0643 \u0623\u0648 \u0633\u0627\u0642\u0643.\n\u0642\u0645 \u0628\u0641\u0631\u062f \u0633\u0627\u0642\u0643 \u0642\u062f\u0631 \u0627\u0644\u0625\u0645\u0643\u0627\u0646 \u0645\u0639 \u0625\u0628\u0642\u0627\u0626\u0647\u0627 \u0645\u0631\u062a\u0641\u0639\u0629.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u062a\u0645\u062f\u062f \u0644\u0645\u062f\u0629 20-30 \u062b\u0627\u0646\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1576","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"hamstrings","secondary_muscles":["glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1576-sU5BrfP.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1576-sU5BrfP.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"db6a1ec2-8921-54f0-8caa-32149b3680c5","source_id":"2287","name_en":"lever alternate leg press","name_ar":"\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0628\u062f\u064a\u0644\u0629 \u0644\u0644\u0633\u0627\u0642","match_names":["lever alternate leg press"],"muscle":"quads","equipment":"machine","aliases":["lever alternate leg press"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat and foot platform of the leverage machine to your desired position.\nSit on the machine with your back against the backrest and your feet on the foot platform.\nPlace your hands on the handles or sides of the machine for stability.\nPush one foot against the foot platform, extending your leg until it is almost fully straight.\nPause for a moment, then slowly bend your leg and return to the starting position.\nRepeat with the other leg.\nContinue alternating legs for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645 \u0644\u0622\u0644\u0629 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0637\u0644\u0648\u0628.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0645\u0642\u0627\u0628\u0636 \u0623\u0648 \u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0627\u062f\u0641\u0639 \u0642\u062f\u0645\u064b\u0627 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645\u060c \u0648\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u0643 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0645\u0633\u062a\u0642\u064a\u0645\u0629 \u062a\u0645\u0627\u0645\u064b\u0627 \u062a\u0642\u0631\u064a\u0628\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629\u060c \u062b\u0645 \u0627\u062b\u0646\u0650 \u0633\u0627\u0642\u0643 \u0628\u0628\u0637\u0621 \u0648\u0627\u0631\u062c\u0639 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0645\u0639 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0623\u062e\u0631\u0649.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u062a\u0628\u062f\u064a\u0644 \u0627\u0644\u0633\u0627\u0642\u064a\u0646 \u0628\u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"2287","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"quads","secondary_muscles":["hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/2287-V07qpXy.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/2287-V07qpXy.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4076fa76-c3fa-5d19-80eb-7f087c7b1336","source_id":"0571","name_en":"lever alternating narrow grip seated row","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0642\u0628\u0636\u0629 \u0636\u064a\u0642\u0629 \u0635\u0641 \u0627\u0644\u062c\u0644\u0648\u0633","match_names":["lever alternating narrow grip seated row"],"muscle":"back","equipment":"machine","aliases":["lever alternating narrow grip seated row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and footplate position to ensure proper alignment.\nSit on the machine with your back straight and feet flat on the footplate.\nGrasp the handles with a narrow grip, palms facing each other.\nKeep your chest up and shoulders back throughout the exercise.\nPull one handle towards your torso while keeping the other handle stationary.\nSqueeze your shoulder blades together at the end of the movement.\nSlowly return the handle to the starting position and repeat with the other side.\nContinue alternating sides for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0648\u0636\u0639 \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0644\u0636\u0645\u0627\u0646 \u0627\u0644\u0645\u062d\u0627\u0630\u0627\u0629 \u0627\u0644\u0635\u062d\u064a\u062d\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0648\u0638\u0647\u0631\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u064b\u0627 \u0648\u0642\u062f\u0645\u0627\u0643 \u0645\u0633\u0637\u062d\u062a\u0627\u0646 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u064a\u0629.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0636\u064a\u0642\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0648\u0627\u062c\u0647 \u0631\u0627\u062d\u062a\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0645\u0631\u062a\u0641\u0639\u064b\u0627 \u0648\u0643\u062a\u0641\u064a\u0643 \u0644\u0644\u062e\u0644\u0641 \u0637\u0648\u0627\u0644 \u0627\u0644\u062a\u0645\u0631\u064a\u0646.\n\u0627\u0633\u062d\u0628 \u0623\u062d\u062f \u0627\u0644\u0645\u0642\u0628\u0636\u064a\u0646 \u0646\u062d\u0648 \u062c\u0630\u0639\u0643 \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0627\u0644\u0645\u0642\u0628\u0636 \u0627\u0644\u0622\u062e\u0631 \u062b\u0627\u0628\u062a\u064b\u0627.\n\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0641\u064a \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u0623\u0639\u062f \u0627\u0644\u0645\u0642\u0628\u0636 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629 \u0648\u0643\u0631\u0631 \u0630\u0644\u0643 \u0645\u0639 \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u0622\u062e\u0631.\n\u0627\u0633\u062a\u0645\u0631 \u0628\u0627\u0644\u062a\u0646\u0627\u0648\u0628 \u0628\u064a\u0646 \u0627\u0644\u062c\u0627\u0646\u0628\u064a\u0646 \u0644\u0644\u062d\u0635\u0648\u0644 \u0639\u0644\u0649 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631\u0627\u062a.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0571","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0571-w2oRpuH.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0571-w2oRpuH.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"3c33d0dd-9ce5-5a46-8b06-2626ecae23f4","source_id":"0572","name_en":"lever assisted chin-up","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0628\u0645\u0633\u0627\u0639\u062f\u0629 \u0627\u0644\u0630\u0642\u0646","match_names":["lever assisted chin-up"],"muscle":"back","equipment":"machine","aliases":["lever assisted chin-up"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the leverage machine to your desired resistance level.\nStand on the foot platform and grip the handles with an overhand grip, slightly wider than shoulder-width apart.\nHang with your arms fully extended, keeping your body straight.\nEngage your back muscles and pull your body up towards the handles, leading with your chest.\nContinue pulling until your chin is above the handles.\nPause for a moment at the top, then slowly lower your body back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0645\u0627\u0644\u064a\u0629 \u0639\u0644\u0649 \u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0645\u0637\u0644\u0648\u0628.\n\u0642\u0641 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645 \u0648\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0634\u0646\u0642 \u0645\u0639 \u0630\u0631\u0627\u0639\u064a\u0643 \u0645\u0645\u062a\u062f\u0629 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0648\u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u062c\u0633\u0645\u0643 \u0645\u0633\u062a\u0642\u064a\u0645\u0627.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643 \u0648\u0627\u0633\u062d\u0628 \u062c\u0633\u0645\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u0646\u062d\u0648 \u0627\u0644\u0645\u0642\u0627\u0628\u0636\u060c \u0645\u0645\u0627 \u064a\u0624\u062f\u064a \u0625\u0644\u0649 \u0635\u062f\u0631\u0643.\n\u0627\u0633\u062a\u0645\u0631 \u0641\u064a \u0627\u0644\u0633\u062d\u0628 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0630\u0642\u0646\u0643 \u0641\u0648\u0642 \u0627\u0644\u0645\u0642\u0627\u0628\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u062c\u0633\u0645\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0572","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"lats","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0572-MaMuGH6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0572-MaMuGH6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"4ad47975-313a-5b44-8a30-a2e1e623004d","source_id":"0573","name_en":"lever back extension","name_ar":"\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u062e\u0644\u0641\u064a\u0629","match_names":["lever back extension"],"muscle":"back","equipment":"machine","aliases":["lever back extension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the machine to fit your body size and range of motion.\nSit on the machine with your back against the pad and your feet secured.\nPlace your hands on the handles or grip bars.\nEngage your core and slowly lean forward, allowing your back to round slightly.\nPause for a moment at the bottom position, feeling a stretch in your lower back.\nUsing your back muscles, slowly raise your torso back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0644\u062c\u0647\u0627\u0632 \u0644\u064a\u0646\u0627\u0633\u0628 \u062d\u062c\u0645 \u062c\u0633\u0645\u0643 \u0648\u0646\u0637\u0627\u0642 \u062d\u0631\u0643\u062a\u0643.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u062a\u0623\u0645\u064a\u0646 \u0642\u062f\u0645\u064a\u0643.\n\u0636\u0639 \u064a\u062f\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0623\u0648 \u0642\u0636\u0628\u0627\u0646 \u0627\u0644\u0642\u0628\u0636\u0629.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0642\u0644\u0628\u0643 \u0648\u062a\u0645\u064a\u0644 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645\u060c \u0645\u0645\u0627 \u064a\u0633\u0645\u062d \u0644\u0638\u0647\u0631\u0643 \u0628\u0627\u0644\u0627\u0644\u062a\u0641\u0627\u0641 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0645\u0648\u0636\u0639 \u0627\u0644\u0633\u0641\u0644\u064a\u060c \u0648\u0633\u062a\u0634\u0639\u0631 \u0628\u062a\u0645\u062f\u062f \u0641\u064a \u0623\u0633\u0641\u0644 \u0638\u0647\u0631\u0643.\n\u0628\u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0639\u0636\u0644\u0627\u062a \u0638\u0647\u0631\u0643\u060c \u0627\u0631\u0641\u0639 \u062c\u0630\u0639\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0573","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"spine","secondary_muscles":["glutes","hamstrings"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0573-rUXfn3R.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0573-rUXfn3R.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"10c772ca-84a2-54d7-815a-2ade38bbcfbd","source_id":"0574","name_en":"lever bent over row","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0639\u0627\u0632\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0635\u0641","match_names":["lever bent over row"],"muscle":"back","equipment":"barbell","aliases":["lever bent over row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Stand with your feet shoulder-width apart and knees slightly bent.\nHold the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\nBend forward at the hips, keeping your back straight and chest up.\nPull the barbell towards your lower chest, squeezing your shoulder blades together.\nPause for a moment at the top, then slowly lower the barbell back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0642\u0641 \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0642\u062f\u0645\u064a\u0643 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646 \u0648\u062b\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u062d\u062f\u064a\u062f \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0645\u0639 \u0645\u0628\u0627\u0639\u062f\u0629 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0634\u0643\u0644 \u0623\u0648\u0633\u0639 \u0642\u0644\u064a\u0644\u064b\u0627 \u0645\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0627\u0646\u062d\u0646\u0649 \u0644\u0644\u0623\u0645\u0627\u0645 \u0639\u0646\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0635\u062f\u0631\u0643 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0628\u0627\u0631 \u0646\u062d\u0648 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0633\u0641\u0644\u064a \u0645\u0646 \u0635\u062f\u0631\u0643\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0627\u0644\u0643\u062a\u0641 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0