062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0576","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"pectorals","secondary_muscles":["triceps","shoulders"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0576-DOoWcnA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0576-DOoWcnA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"8bf54e04-8b15-5b6e-8937-1da91b46ea81","source_id":"0578","name_en":"lever deadlift","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0631\u0641\u0639\u0629 \u0627\u0644\u0645\u0645\u064a\u062a\u0629","match_names":["lever deadlift"],"muscle":"glutes","equipment":"machine","aliases":["lever deadlift"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and foot platform to your desired position.\nSit on the machine with your back against the pad and your feet flat on the foot platform.\nGrasp the handles or the sides of the seat for stability.\nEngage your glutes and hamstrings, and push through your heels to lift the weight up.\nKeep your back straight and avoid rounding your shoulders.\nExtend your hips fully at the top of the movement, squeezing your glutes.\nLower the weight back down in a controlled manner, keeping tension on your glutes and hamstrings.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645 \u0639\u0644\u0649 \u0627\u0644\u0648\u0636\u0639 \u0627\u0644\u0645\u0631\u063a\u0648\u0628 \u0641\u064a\u0647.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0645\u0646\u0635\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0623\u0645\u0633\u0643 \u0645\u0642\u0627\u0628\u0636 \u0623\u0648 \u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0645\u0642\u0639\u062f \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0639\u0636\u0644\u0627\u062a \u0627\u0644\u0645\u0624\u062e\u0631\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629\u060c \u0648\u0627\u062f\u0641\u0639 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0643\u0639\u0628\u064a\u0643 \u0644\u0631\u0641\u0639 \u0627\u0644\u0648\u0632\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062a\u062c\u0646\u0628 \u062a\u0642\u0631\u064a\u0628 \u0643\u062a\u0641\u064a\u0643.\n\u0642\u0645 \u0628\u062a\u0645\u062f\u064a\u062f \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0628\u0627\u0644\u0643\u0627\u0645\u0644 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u0645\u0639 \u0627\u0644\u0636\u063a\u0637 \u0639\u0644\u0649 \u0627\u0644\u0623\u0631\u062f\u0627\u0641.\n\u0642\u0645 \u0628\u062e\u0641\u0636 \u0627\u0644\u0648\u0632\u0646 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062d\u0643\u0645\u0629\u060c \u0645\u0639 \u0627\u0644\u062d\u0641\u0627\u0638 \u0639\u0644\u0649 \u0627\u0644\